-- DP-108 (ADR-018, owner decisions K1-K5 and conditions 1-9 of 2026-11-12): the system owner (GOD).
--
-- Runs as dp_owner (ADR-012A). Additive: no table, column or row is removed, and no existing row
-- changes (every existing audit event stays STANDARD; nothing is classified retroactively).
--
-- Part 1 (generated by Prisma): AuditStream, the hash-chain columns of AuditEvent, SystemOwner and
-- SystemOwnerDesignation.
-- Part 2 (rules Prisma cannot model):
--  2.1 CHECK constraints.
--  2.2 SystemOwner: at most one row, inserted only by iam_owner_designation_confirm, never changed
--      or removed (non-transferable). Designations are evidence and are never deleted.
--  2.3 The owner account is out of reach of everyone else: outside the owner's SECURITY DEFINER
--      functions (current_user = dp_owner) nobody can suspend or close it, take its password or
--      MFA away, revoke its sessions as an administrator, give or take its roles, issue it an
--      enrolment, invitation, re-enrolment, recovery or reset link, or change its e-mail. The
--      system_owner role is never assignable.
--  2.4 PROTECTED audit stream: a SECURITY DEFINER trigger classifies every new event (the caller's
--      value is ignored) and chains PROTECTED events with SHA-256; iam_verify_protected_audit_chain
--      recomputes the chain.
--  2.5 Operator functions (SECURITY DEFINER, owned by dp_owner): designation start and owner
--      recovery for dp_iam_bootstrap only (never the API's role, condition 1); designation confirm
--      for dp_app, which needs the link token that only the operator CLI can create.
--  2.6 Privileges.
-- Tested in test/integration/owner.int.test.ts.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dp_iam_bootstrap')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dp_app') THEN
    RAISE EXCEPTION 'DP-108: the ADR-012A database roles are missing; run infra/docker/stack.sh db-roles first';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'iam_db_audit') THEN
    RAISE EXCEPTION 'DP-108: migration 20261111090000_f1_002_authentication must be applied first';
  END IF;
END $$;

-- =============================================================================================
-- Part 1 (prisma migrate diff)
-- =============================================================================================

-- CreateEnum
CREATE TYPE "AuditStream" AS ENUM ('STANDARD', 'PROTECTED');

-- AlterTable
ALTER TABLE "AuditEvent" ADD COLUMN     "chainSeq" BIGINT,
ADD COLUMN     "prevHash" CHAR(64),
ADD COLUMN     "rowHash" CHAR(64),
ADD COLUMN     "stream" "AuditStream" NOT NULL DEFAULT 'STANDARD';

-- CreateTable
CREATE TABLE "SystemOwner" (
    "id" BOOLEAN NOT NULL DEFAULT true,
    "userId" UUID NOT NULL,
    "designatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "designationId" UUID NOT NULL,

    CONSTRAINT "SystemOwner_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "SystemOwnerDesignation" (
    "id" UUID NOT NULL,
    "userId" UUID NOT NULL,
    "tokenHash" CHAR(64) NOT NULL,
    "reason" VARCHAR(1000) NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMPTZ(3) NOT NULL,
    "consumedAt" TIMESTAMPTZ(3),
    "invalidatedAt" TIMESTAMPTZ(3),
    "failedAttempts" INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT "SystemOwnerDesignation_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "SystemOwner_userId_key" ON "SystemOwner"("userId");

-- CreateIndex
CREATE UNIQUE INDEX "SystemOwner_designationId_key" ON "SystemOwner"("designationId");

-- CreateIndex
CREATE UNIQUE INDEX "SystemOwnerDesignation_tokenHash_key" ON "SystemOwnerDesignation"("tokenHash");

-- CreateIndex
CREATE INDEX "SystemOwnerDesignation_userId_idx" ON "SystemOwnerDesignation"("userId");

-- CreateIndex
CREATE UNIQUE INDEX "AuditEvent_chainSeq_key" ON "AuditEvent"("chainSeq");

-- CreateIndex
CREATE INDEX "AuditEvent_stream_occurredAt_idx" ON "AuditEvent"("stream", "occurredAt");

-- AddForeignKey
ALTER TABLE "SystemOwner" ADD CONSTRAINT "SystemOwner_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "SystemOwner" ADD CONSTRAINT "SystemOwner_designationId_fkey" FOREIGN KEY ("designationId") REFERENCES "SystemOwnerDesignation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "SystemOwnerDesignation" ADD CONSTRAINT "SystemOwnerDesignation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- =============================================================================================
-- Part 2
-- =============================================================================================

-- 2.1 CHECK constraints -----------------------------------------------------------------------

ALTER TABLE "SystemOwner"
  ADD CONSTRAINT "SystemOwner_singleton_check" CHECK ("id");

ALTER TABLE "SystemOwnerDesignation"
  ADD CONSTRAINT "SystemOwnerDesignation_tokenHash_check" CHECK ("tokenHash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "SystemOwnerDesignation_reason_check" CHECK (length(btrim("reason")) >= 10),
  ADD CONSTRAINT "SystemOwnerDesignation_expiry_check" CHECK ("expiresAt" > "createdAt"),
  ADD CONSTRAINT "SystemOwnerDesignation_failedAttempts_check"
    CHECK ("failedAttempts" BETWEEN 0 AND 5);

-- Every existing row is STANDARD with no chain fields, so validating this scans and passes.
ALTER TABLE "AuditEvent"
  ADD CONSTRAINT "AuditEvent_stream_chain_check" CHECK (
    ("stream" = 'STANDARD' AND "chainSeq" IS NULL AND "prevHash" IS NULL AND "rowHash" IS NULL)
    OR ("stream" = 'PROTECTED' AND "chainSeq" > 0
        AND "prevHash" ~ '^[0-9a-f]{64}$' AND "rowHash" ~ '^[0-9a-f]{64}$'));

-- 2.2 The owner record ----------------------------------------------------------------------

-- The owner's user id, or NULL before the designation. SECURITY DEFINER so that the guard
-- triggers can use it whichever role fires them (dp_iam_bootstrap cannot read SystemOwner itself
-- in every statement it runs).
CREATE FUNCTION iam_system_owner_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $fn$
  SELECT "userId" FROM "SystemOwner" WHERE "id"
$fn$;

-- Insert only inside iam_owner_designation_confirm (dp_owner with the transaction-local flag);
-- update, delete and the table-wide statement are refused for everyone, dp_owner included. A
-- legal successor is registered only by a reviewed migration (ADR-018 D9).
CREATE FUNCTION iam_system_owner_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF current_user = 'dp_owner' AND current_setting('iam.owner_designation', true) = 'on' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'iam: the system owner is designated only through iam_owner_designation_confirm (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RAISE EXCEPTION 'iam: the system owner cannot be changed, handed on or removed (DP-108, % rejected)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$fn$;
CREATE TRIGGER "SystemOwner_guard" BEFORE INSERT OR UPDATE OR DELETE ON "SystemOwner"
  FOR EACH ROW EXECUTE FUNCTION iam_system_owner_guard();
CREATE TRIGGER "SystemOwner_no_truncate" BEFORE TRUNCATE ON "SystemOwner"
  FOR EACH STATEMENT EXECUTE FUNCTION iam_system_owner_guard();

-- Designations are evidence: only the owner functions write them, nobody deletes them.
CREATE FUNCTION iam_owner_designation_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
    RAISE EXCEPTION 'iam: owner designations are evidence and cannot be deleted (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_user <> 'dp_owner' THEN
    RAISE EXCEPTION 'iam: owner designations are written only by the owner functions (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW."id" IS DISTINCT FROM OLD."id" OR NEW."userId" IS DISTINCT FROM OLD."userId"
      OR NEW."tokenHash" IS DISTINCT FROM OLD."tokenHash" OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt"
      OR (OLD."consumedAt" IS NOT NULL AND NEW."consumedAt" IS DISTINCT FROM OLD."consumedAt")
      OR (OLD."invalidatedAt" IS NOT NULL AND NEW."invalidatedAt" IS DISTINCT FROM OLD."invalidatedAt")) THEN
    RAISE EXCEPTION 'iam: an owner designation changes only its state, once (DP-108)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "SystemOwnerDesignation_guard" BEFORE INSERT OR UPDATE OR DELETE ON "SystemOwnerDesignation"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_designation_guard();
CREATE TRIGGER "SystemOwnerDesignation_no_truncate" BEFORE TRUNCATE ON "SystemOwnerDesignation"
  FOR EACH STATEMENT EXECUTE FUNCTION iam_owner_designation_guard();

-- 2.3 The owner account is out of everyone else's reach ---------------------------------------
-- "Everyone else" is every role except dp_owner, i.e. the API (dp_app) and the bootstrap
-- credential outside the owner functions. Inside a SECURITY DEFINER function owned by dp_owner,
-- current_user is dp_owner; dp_app can never become dp_owner (ADR-012A).

CREATE FUNCTION iam_owner_user_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF current_user = 'dp_owner' OR OLD."id" IS DISTINCT FROM iam_system_owner_id() THEN
    RETURN NEW;
  END IF;
  IF NEW."status" IS DISTINCT FROM OLD."status" AND NEW."status" IN ('SUSPENDED', 'DEACTIVATED') THEN
    RAISE EXCEPTION 'iam: the system owner account cannot be suspended or closed (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF (OLD."status" = 'ACTIVE' AND NEW."status" = 'PENDING')
     OR (OLD."passwordHash" IS NOT NULL AND NEW."passwordHash" IS NULL)
     OR (OLD."mfaEnrolledAt" IS NOT NULL AND NEW."mfaEnrolledAt" IS NULL) THEN
    RAISE EXCEPTION 'iam: the system owner account is reset only by the owner recovery (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."email" IS DISTINCT FROM OLD."email" OR NEW."emailNormalized" IS DISTINCT FROM OLD."emailNormalized" THEN
    RAISE EXCEPTION 'iam: the system owner e-mail cannot be changed (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "User_system_owner_guard" BEFORE UPDATE ON "User"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_user_guard();

-- A confirmed factor of the owner is never deleted or re-keyed by anyone else (MFA reset). It is
-- replaced only by the re-enrolment that follows an owner recovery. Unconfirmed factors and
-- recovery codes follow the normal rules: the owner regenerates its own codes.
CREATE FUNCTION iam_owner_mfa_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF current_user = 'dp_owner' OR OLD."confirmedAt" IS NULL
     OR OLD."userId" IS DISTINCT FROM iam_system_owner_id() THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    -- After iam_owner_recover the account is PENDING without MFA, a state nobody else can bring
    -- the owner into (iam_owner_user_guard); the re-enrolment then replaces the old factor.
    IF EXISTS (SELECT 1 FROM "User" u WHERE u."id" = OLD."userId"
               AND u."status" = 'PENDING' AND u."mfaEnrolledAt" IS NULL) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'iam: the system owner MFA factor is reset only by the owner recovery (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."secretCiphertext" IS DISTINCT FROM OLD."secretCiphertext" THEN
    RAISE EXCEPTION 'iam: the system owner MFA factor is reset only by the owner recovery (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "MfaFactor_system_owner_guard" BEFORE UPDATE OR DELETE ON "MfaFactor"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_mfa_guard();

-- Links that let someone set the owner's password or MFA (enrolment, invitation, re-enrolment,
-- recovery, reset) come only from iam_owner_recover. The login MFA challenge stays possible.
CREATE FUNCTION iam_owner_token_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF current_user <> 'dp_owner' AND NEW."purpose" <> 'LOGIN_MFA_CHALLENGE'
     AND NEW."userId" = iam_system_owner_id() THEN
    RAISE EXCEPTION 'iam: credential links for the system owner come only from the owner recovery (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "UserCredentialToken_system_owner_guard" BEFORE INSERT ON "UserCredentialToken"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_token_guard();

-- system_owner is never assignable (condition 6), for every role including dp_owner. The owner
-- receives no role from anyone else and its existing assignments cannot be revoked or expired by
-- anyone else.
CREATE FUNCTION iam_owner_assignment_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  owner_id uuid;
BEGIN
  IF TG_OP = 'INSERT'
     AND (SELECT r."key" FROM "Role" r WHERE r."id" = NEW."roleId") = 'system_owner' THEN
    RAISE EXCEPTION 'iam: system_owner is not an assignable role (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_user = 'dp_owner' THEN
    RETURN NEW;
  END IF;
  owner_id := iam_system_owner_id();
  IF owner_id IS NULL OR NEW."userId" IS DISTINCT FROM owner_id THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'iam: no role can be assigned to the system owner (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."revokedAt" IS DISTINCT FROM OLD."revokedAt" OR NEW."expiresAt" IS DISTINCT FROM OLD."expiresAt" THEN
    RAISE EXCEPTION 'iam: the system owner role assignments cannot be changed (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
-- Named so that it fires before RoleAssignment_reciprocal_guard (triggers fire in name order): the
-- owner rule is the decisive refusal, whatever the grant chain looks like.
CREATE TRIGGER "RoleAssignment_owner_guard" BEFORE INSERT OR UPDATE ON "RoleAssignment"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_assignment_guard();

-- No administrator revokes the owner's sessions (the owner's own logout and the security-version
-- revocation of its own password change stay possible).
CREATE FUNCTION iam_owner_session_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF current_user <> 'dp_owner' AND OLD."revokedAt" IS NULL
     AND NEW."revokedReason" = 'ADMIN_REVOKED'
     AND OLD."userId" = iam_system_owner_id() THEN
    RAISE EXCEPTION 'iam: the system owner sessions cannot be revoked by an administrator (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "Session_system_owner_guard" BEFORE UPDATE ON "Session"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_session_guard();

CREATE FUNCTION iam_owner_membership_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $fn$
BEGIN
  IF current_user <> 'dp_owner' AND NEW."status" IS DISTINCT FROM OLD."status"
     AND NEW."status" IN ('SUSPENDED', 'REVOKED')
     AND OLD."userId" = iam_system_owner_id() THEN
    RAISE EXCEPTION 'iam: the system owner memberships cannot be suspended or revoked (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "Membership_system_owner_guard" BEFORE UPDATE ON "Membership"
  FOR EACH ROW EXECUTE FUNCTION iam_owner_membership_guard();

-- 2.4 PROTECTED audit stream and its hash chain ---------------------------------------------

-- Canonical text of an event, hashed with SHA-256. The verifier uses the same function.
CREATE FUNCTION iam_audit_row_hash(e "AuditEvent") RETURNS text LANGUAGE sql STABLE
SET search_path = pg_catalog, public, pg_temp AS $fn$
  SELECT encode(sha256(convert_to(concat_ws('|',
    e."chainSeq"::text, e."prevHash", e."id"::text,
    to_char(e."occurredAt" AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    e."actorType"::text, coalesce(e."actorUserId"::text, ''), e."action", e."resourceType",
    coalesce(e."resourceId", ''), e."scopeType"::text, coalesce(e."siteId"::text, ''),
    e."outcome"::text, coalesce(e."reason", ''), e."metadata"::text, coalesce(e."requestId", '')
  ), 'UTF8')), 'hex')
$fn$;

-- The stream is decided here, never by the caller. PROTECTED: owner.* actions, the owner's own
-- actions, and every event about the owner account, its role assignments, links and sessions.
-- SECURITY DEFINER: it reads SystemOwner and the chain head whichever role inserts the event
-- (dp_iam_bootstrap may only insert audit rows). pg_advisory_xact_lock key "IAMCHAIN".
CREATE FUNCTION iam_audit_event_protected_stream() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  owner_id uuid := iam_system_owner_id();
  about_owner boolean := false;
  prev_seq bigint;
  prev_hash text;
BEGIN
  IF owner_id IS NOT NULL THEN
    about_owner :=
      NEW."actorUserId" = owner_id
      OR (NEW."resourceType" = 'user' AND NEW."resourceId" = owner_id::text)
      OR NEW."metadata"->>'userId' = owner_id::text
      OR NEW."metadata"->>'assigneeUserId' = owner_id::text
      OR NEW."metadata"->>'targetUserId' = owner_id::text
      OR (NEW."resourceType" = 'credential_token'
          AND NEW."resourceId" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND EXISTS (SELECT 1 FROM "UserCredentialToken" t
                      WHERE t."id" = NEW."resourceId"::uuid AND t."userId" = owner_id))
      OR (NEW."resourceType" = 'session'
          AND NEW."resourceId" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND EXISTS (SELECT 1 FROM "Session" s
                      WHERE s."id" = NEW."resourceId"::uuid AND s."userId" = owner_id))
      OR (NEW."resourceType" = 'role_assignment'
          AND NEW."resourceId" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND EXISTS (SELECT 1 FROM "RoleAssignment" a
                      WHERE a."id" = NEW."resourceId"::uuid AND a."userId" = owner_id));
  END IF;
  IF NEW."action" LIKE 'owner.%' OR coalesce(about_owner, false) THEN
    NEW."stream" := 'PROTECTED';
  ELSE
    NEW."stream" := 'STANDARD';
    NEW."chainSeq" := NULL;
    NEW."prevHash" := NULL;
    NEW."rowHash" := NULL;
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(x'49414d434841494e'::bigint);
  SELECT e."chainSeq", e."rowHash" INTO prev_seq, prev_hash
  FROM "AuditEvent" e WHERE e."stream" = 'PROTECTED'
  ORDER BY e."chainSeq" DESC LIMIT 1;
  NEW."chainSeq" := coalesce(prev_seq, 0) + 1;
  NEW."prevHash" := coalesce(prev_hash, repeat('0', 64));
  NEW."rowHash" := iam_audit_row_hash(NEW);
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "AuditEvent_protected_stream" BEFORE INSERT ON "AuditEvent"
  FOR EACH ROW EXECUTE FUNCTION iam_audit_event_protected_stream();

-- Recomputes the chain: number of PROTECTED events, the first broken link (NULL = intact), and
-- the head (sequence and hash) that an external checkpoint can record (DP-112).
CREATE FUNCTION iam_verify_protected_audit_chain()
RETURNS TABLE ("events" bigint, "firstBrokenSeq" bigint, "headSeq" bigint, "headHash" text)
LANGUAGE plpgsql STABLE
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  r record;
  n bigint := 0;
  broken bigint;
  expected_prev text := repeat('0', 64);
  last_seq bigint := 0;
BEGIN
  FOR r IN
    SELECT e AS ev, e."chainSeq" AS seq, e."prevHash" AS prev, e."rowHash" AS hash
    FROM "AuditEvent" e WHERE e."stream" = 'PROTECTED'
    ORDER BY e."chainSeq" NULLS LAST
  LOOP
    n := n + 1;
    IF broken IS NULL AND (r.seq IS DISTINCT FROM n OR r.prev IS DISTINCT FROM expected_prev
        OR r.hash IS DISTINCT FROM iam_audit_row_hash(r.ev)) THEN
      broken := coalesce(r.seq, 0);
    END IF;
    expected_prev := r.hash;
    last_seq := coalesce(r.seq, last_seq);
  END LOOP;
  RETURN QUERY SELECT n, broken, last_seq, CASE WHEN n = 0 THEN NULL ELSE expected_prev END;
END
$fn$;

-- 2.5 Operator functions -------------------------------------------------------------------
-- pg_advisory_xact_lock key "IAMOWNER" serialises designation and recovery.

-- Started by `iam-cli owner-designate` (dp_iam_bootstrap). The CLI keeps the raw token and prints
-- the link once; only its SHA-256 is stored. Any older pending designation dies.
CREATE FUNCTION iam_owner_designation_start(p_user_id uuid, p_token_hash text, p_reason text)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  u record;
  d_id uuid := iam_uuid_v7();
  expires timestamptz := now() + interval '30 minutes';
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'iam: invalid token hash' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'iam: the reason needs at least 10 characters' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM pg_advisory_xact_lock(x'49414d4f574e4552'::bigint);
  IF EXISTS (SELECT 1 FROM "SystemOwner") THEN
    RAISE EXCEPTION 'iam: the system owner is already designated and cannot be changed (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT "id", "kind", "status", "passwordHash", "mfaEnrolledAt" INTO u
  FROM "User" WHERE "id" = p_user_id FOR UPDATE;
  IF NOT FOUND OR u."kind" <> 'STAFF' OR u."status" <> 'ACTIVE'
     OR u."passwordHash" IS NULL OR u."mfaEnrolledAt" IS NULL THEN
    RAISE EXCEPTION 'iam: the owner must be an ACTIVE staff account with a password and MFA'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  UPDATE "SystemOwnerDesignation" SET "invalidatedAt" = now()
  WHERE "consumedAt" IS NULL AND "invalidatedAt" IS NULL;
  INSERT INTO "SystemOwnerDesignation" ("id", "userId", "tokenHash", "reason", "createdAt", "expiresAt")
  VALUES (d_id, p_user_id, p_token_hash, btrim(p_reason), now(), expires);
  INSERT INTO "AuditEvent"
    ("id", "actorType", "action", "resourceType", "resourceId", "scopeType", "outcome", "reason", "metadata")
  VALUES (iam_uuid_v7(), 'BOOTSTRAP', 'owner.designation_started', 'user', p_user_id::text, 'PLATFORM',
          'SUCCESS', btrim(p_reason),
          jsonb_build_object('designationId', d_id, 'expiresAt', expires, 'dbUser', session_user::text));
  RETURN expires;
END
$fn$;

-- Called by the API (dp_app) for a signed-in staff user who opened the link and passed password
-- and step-up checks in the API. The token proves the operator started this designation for
-- this user; without it nothing happens. Returns designated | invalid | not_eligible |
-- already_designated (failures are counted on the designation, never raised, so they persist).
CREATE FUNCTION iam_owner_designation_confirm(p_user_id uuid, p_token_hash text, p_request_id text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  d record;
  u record;
BEGIN
  PERFORM pg_advisory_xact_lock(x'49414d4f574e4552'::bigint);
  IF EXISTS (SELECT 1 FROM "SystemOwner") THEN
    RETURN 'already_designated';
  END IF;
  SELECT * INTO d FROM "SystemOwnerDesignation"
  WHERE "userId" = p_user_id AND "consumedAt" IS NULL AND "invalidatedAt" IS NULL
  ORDER BY "createdAt" DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'invalid';
  END IF;
  IF d."expiresAt" <= now() THEN
    UPDATE "SystemOwnerDesignation" SET "invalidatedAt" = now() WHERE "id" = d."id";
    RETURN 'invalid';
  END IF;
  IF p_token_hash IS NULL OR p_token_hash IS DISTINCT FROM d."tokenHash" THEN
    UPDATE "SystemOwnerDesignation"
    SET "failedAttempts" = d."failedAttempts" + 1,
        "invalidatedAt" = CASE WHEN d."failedAttempts" + 1 >= 5 THEN now() END
    WHERE "id" = d."id";
    RETURN 'invalid';
  END IF;
  SELECT "kind", "status", "passwordHash", "mfaEnrolledAt" INTO u FROM "User" WHERE "id" = p_user_id;
  IF NOT FOUND OR u."kind" <> 'STAFF' OR u."status" <> 'ACTIVE'
     OR u."passwordHash" IS NULL OR u."mfaEnrolledAt" IS NULL THEN
    RETURN 'not_eligible';
  END IF;
  UPDATE "SystemOwnerDesignation" SET "consumedAt" = now() WHERE "id" = d."id";
  PERFORM set_config('iam.owner_designation', 'on', true);
  INSERT INTO "SystemOwner" ("id", "userId", "designatedAt", "designationId")
  VALUES (true, p_user_id, now(), d."id");
  PERFORM set_config('iam.owner_designation', 'off', true);
  INSERT INTO "AuditEvent"
    ("id", "actorType", "actorUserId", "action", "resourceType", "resourceId", "scopeType", "outcome",
     "metadata", "requestId")
  VALUES (iam_uuid_v7(), 'USER', p_user_id, 'owner.designated', 'user', p_user_id::text, 'PLATFORM',
          'SUCCESS', jsonb_build_object('designationId', d."id"), left(p_request_id, 100));
  RETURN 'designated';
END
$fn$;

-- `iam-cli owner-recover` (dp_iam_bootstrap): the owner lost password and MFA. Clears both (the
-- account must enrol again), spends the recovery codes, ends every session and link, and stores an ADMIN_RECOVERY link (30 minutes) whose raw token only the
-- CLI saw. The owner stays the same user: recovery never moves ownership.
CREATE FUNCTION iam_owner_recover(p_user_id uuid, p_token_hash text, p_reason text)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp AS $fn$
DECLARE
  sv integer;
  sessions_revoked integer;
  expires timestamptz := now() + interval '30 minutes';
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'iam: invalid token hash' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'iam: the reason needs at least 10 characters' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM pg_advisory_xact_lock(x'49414d4f574e4552'::bigint);
  IF p_user_id IS DISTINCT FROM iam_system_owner_id() THEN
    RAISE EXCEPTION 'iam: owner-recover is only for the system owner account (DP-108)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- The old factor stays until the re-enrolment replaces it (iam_owner_mfa_guard); it is useless
  -- meanwhile because a PENDING account cannot sign in. Unused recovery codes are spent.
  UPDATE "MfaRecoveryCode" SET "usedAt" = now() WHERE "userId" = p_user_id AND "usedAt" IS NULL;
  UPDATE "User"
  SET "status" = 'PENDING', "passwordHash" = NULL, "mfaEnrolledAt" = NULL,
      "securityVersion" = "securityVersion" + 1, "updatedAt" = now()
  WHERE "id" = p_user_id
  RETURNING "securityVersion" INTO sv;
  UPDATE "Session" SET "revokedAt" = now(), "revokedReason" = 'SECURITY_VERSION'
  WHERE "userId" = p_user_id AND "revokedAt" IS NULL;
  GET DIAGNOSTICS sessions_revoked = ROW_COUNT;
  UPDATE "UserCredentialToken" SET "invalidatedAt" = now()
  WHERE "userId" = p_user_id AND "consumedAt" IS NULL AND "invalidatedAt" IS NULL;
  INSERT INTO "UserCredentialToken"
    ("id", "userId", "purpose", "tokenHash", "securityVersion", "app", "expiresAt", "createdAt",
     "createdByType")
  VALUES (iam_uuid_v7(), p_user_id, 'ADMIN_RECOVERY', p_token_hash, sv, 'ADMIN', expires, now(),
          'BOOTSTRAP');
  INSERT INTO "AuditEvent"
    ("id", "actorType", "action", "resourceType", "resourceId", "scopeType", "outcome", "reason", "metadata")
  VALUES (iam_uuid_v7(), 'BOOTSTRAP', 'owner.recovery_issued', 'user', p_user_id::text, 'PLATFORM',
          'SUCCESS', btrim(p_reason),
          jsonb_build_object('revokedCount', sessions_revoked, 'expiresAt', expires,
                             'dbUser', session_user::text));
  RETURN expires;
END
$fn$;

-- 2.6 Privileges -------------------------------------------------------------------------------
-- Default privileges gave dp_app DML on the new tables (ADR-012A); take back what it must not do.
REVOKE ALL ON TABLE "SystemOwnerDesignation" FROM dp_app;
REVOKE INSERT, UPDATE, DELETE ON TABLE "SystemOwner" FROM dp_app;
GRANT SELECT ON TABLE "SystemOwner" TO dp_iam_bootstrap;

REVOKE ALL ON FUNCTION iam_owner_designation_start(uuid, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION iam_owner_recover(uuid, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION iam_owner_designation_confirm(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION iam_owner_designation_start(uuid, text, text) TO dp_iam_bootstrap;
GRANT EXECUTE ON FUNCTION iam_owner_recover(uuid, text, text) TO dp_iam_bootstrap;
GRANT EXECUTE ON FUNCTION iam_owner_designation_confirm(uuid, text, text) TO dp_app;
